  self.config.write_text(json.dumps(cfg));self.config.chmod(0o600)
  self.env={**os.environ,'GOMAXPROCS':'2','HELM_DRIVER':'secret','HELM_CACHE_HOME':str(self.root/'cache'),'HELM_CONFIG_HOME':str(self.root/'helm-config'),'HELM_DATA_HOME':str(self.root/'helm-data')}
  version=subprocess.check_output(['helm','version','--short'],env=self.env,text=True,timeout=4)
